package com.deardiary.privateapp;
import android.app.*;import android.content.*;import android.graphics.Color;import android.net.Uri;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;
/** Untrusted site content never receives a diary bridge or diary WebView storage. */
public final class InstagramActivity extends Activity{
 private WebView web;private boolean closing=false,started=false;
 static boolean allowed(Uri u){if(u==null||!"https".equals(u.getScheme())||u.getUserInfo()!=null||(u.getPort()!=-1&&u.getPort()!=443))return false;String h=u.getHost();return "instagram.com".equals(h)||"www.instagram.com".equals(h)||"m.instagram.com".equals(h)||"i.instagram.com".equals(h)||"facebook.com".equals(h)||"www.facebook.com".equals(h)||"m.facebook.com".equals(h)||"accountscenter.instagram.com".equals(h);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);
  ComponentName caller=getCallingActivity();long issued=getIntent().getLongExtra("issued",0);if(caller==null||!getPackageName().equals(caller.getPackageName())||!MainActivity.class.getName().equals(caller.getClassName())||(saved==null&&(issued<=0||SystemClock.elapsedRealtime()-issued<0||SystemClock.elapsedRealtime()-issued>5000))){finish();return;}
  LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);
  FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.WHITE);setContentView(root);configureInsets(root);root.addView(content,new FrameLayout.LayoutParams(-1,-1));
  web=new WebView(this);content.addView(web,new LinearLayout.LayoutParams(-1,0,1));boolean dark=getIntent().getBooleanExtra("dark",false);InstagramNav nav=new InstagramNav(this,dark,key->{if(!"reels".equals(key)){setResult(RESULT_OK,new Intent().putExtra("tab",key));shut();}});addNavigation(content,nav);WebView.setWebContentsDebuggingEnabled(false);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setGeolocationEnabled(false);s.setSupportMultipleWindows(false);s.setJavaScriptCanOpenWindowsAutomatically(false);s.setMediaPlaybackRequiresUserGesture(true);s.setSaveFormData(false);s.setSafeBrowsingEnabled(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setFilterTouchesWhenObscured(true);
  web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest r){r.deny();}@Override public void onGeolocationPermissionsShowPrompt(String origin,GeolocationPermissions.Callback c){c.invoke(origin,false,false);}@Override public boolean onShowFileChooser(WebView w,android.webkit.ValueCallback<Uri[]> cb,FileChooserParams p){cb.onReceiveValue(null);return true;}});
  web.setDownloadListener((url,agent,disposition,mime,size)->notice("Downloads are disabled in this screen."));
  web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){if(!"https".equals(r.getUrl().getScheme()))return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));return null;}@Override public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(allowed(r.getUrl()))return false;if(r.isForMainFrame())notice("This link is outside the allowed Instagram login sites.");return true;}@Override public void onPageStarted(WebView w,String url,android.graphics.Bitmap icon){if(!allowed(Uri.parse(url))){w.stopLoading();notice("Blocked an unsupported address.");}}@Override public void onReceivedSslError(WebView w,SslErrorHandler h,android.net.http.SslError e){h.cancel();notice("Secure connection failed. Close and try later.");}@Override public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())notice("Instagram could not load. Close and try again.");}});
  started=true;boolean restored=saved!=null&&web.restoreState(saved)!=null&&allowed(Uri.parse(web.getUrl()));if(!restored)web.loadUrl("https://www.instagram.com/reels/");
 }
 static void addNavigation(LinearLayout content,InstagramNav nav){content.addView(nav,new LinearLayout.LayoutParams(-1,-2));}
 static int safeBottom(int system,int ime){return Math.max(system,ime);}
 private void configureInsets(FrameLayout root){
  getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.WHITE);
  getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR|View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);
  if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);
  getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);
  if(Build.VERSION.SDK_INT>=28){WindowManager.LayoutParams lp=getWindow().getAttributes();lp.layoutInDisplayCutoutMode=WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;getWindow().setAttributes(lp);}
  root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());int ime=insets.getInsets(WindowInsets.Type.ime()).bottom;v.setPadding(bars.left,bars.top,bars.right,safeBottom(bars.bottom,ime));}else{int left=insets.getSystemWindowInsetLeft(),right=insets.getSystemWindowInsetRight(),top=insets.getSystemWindowInsetTop(),bottom=insets.getSystemWindowInsetBottom();if(Build.VERSION.SDK_INT>=28&&insets.getDisplayCutout()!=null){DisplayCutout c=insets.getDisplayCutout();left=Math.max(left,c.getSafeInsetLeft());right=Math.max(right,c.getSafeInsetRight());top=Math.max(top,c.getSafeInsetTop());bottom=Math.max(bottom,c.getSafeInsetBottom());}v.setPadding(left,top,right,bottom);}return Build.VERSION.SDK_INT>=30?WindowInsets.CONSUMED:insets.consumeSystemWindowInsets().consumeStableInsets().consumeDisplayCutout();});root.requestApplyInsets();
 }
 private void notice(String text){Toast.makeText(this,text,Toast.LENGTH_LONG).show();}
 private void shut(){if(closing)return;closing=true;if(web!=null){web.stopLoading();web.onPause();web.loadUrl("about:blank");((android.view.ViewGroup)web.getParent()).removeView(web);web.destroy();web=null;}finish();}
 @Override public void onBackPressed(){if(web!=null&&web.canGoBack())web.goBack();else shut();}
 @Override protected void onPause(){super.onPause();if(web!=null)web.onPause();}
 @Override protected void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override protected void onSaveInstanceState(Bundle state){if(web!=null)web.saveState(state);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){if(web!=null){web.destroy();web=null;}super.onDestroy();}
}
